"""Generate a full notebook with inline implementations and tracked source equivalence.

The builder strips package-local imports/CLI wrappers, so the notebook executes
its own definitions. It does not execute source files or import src modules.
"""
from __future__ import annotations
import ast
import hashlib
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

class NotebookTransformer(ast.NodeTransformer):
    def visit_ImportFrom(self,node):
        if node.module and node.module.split('.')[0] in {'src','config'}:
            return None
        return node
    def visit_If(self,node):
        if isinstance(node.test,ast.Compare) and ast.unparse(node.test)=="__name__ == '__main__'":
            return None
        if isinstance(node.test,ast.Name) and node.test.id=='TYPE_CHECKING':
            return None
        return self.generic_visit(node)
    def visit_FunctionDef(self,node):
        if node.name=='main':
            return None
        return self.generic_visit(node)
    def visit_Assign(self,node):
        if any(isinstance(target,ast.Name) and target.id in {'ROOT','PROJECT_ROOT'} for target in node.targets):
            node.value=ast.parse("Path.cwd() if (Path.cwd() / 'src').is_dir() else Path.cwd().parent",mode='eval').body
        return self.generic_visit(node)

def inline_source(relative: str) -> str:
    tree=NotebookTransformer().visit(ast.parse((ROOT/relative).read_text(encoding='utf-8')))
    return ast.unparse(ast.fix_missing_locations(tree))+'\n'

def build_notebook() -> Path:
    cells=[]
    def markdown(text):
        cells.append({'cell_type':'markdown','id':f'cell-{len(cells):03d}','metadata':{},'source':text.splitlines(keepends=True)})
    def code(text,source_module=None):
        metadata={}
        if source_module:
            metadata={'pcb_source_module':source_module,'pcb_source_sha256':hashlib.sha256((ROOT/source_module).read_bytes()).hexdigest(),
                      'pcb_inline_sha256':hashlib.sha256(text.encode()).hexdigest()}
        cells.append({'cell_type':'code','id':f'cell-{len(cells):03d}','metadata':metadata,'source':text.splitlines(keepends=True),'outputs':[],'execution_count':None})
    def section(number,title,text,source=None,example=None):
        markdown(f'## {number}. {title}\n\n{text}\n')
        if source:code(inline_source(source),source)
        if example:code(example)
    markdown('# PCB Vision AI ? Complete implementation and academic notebook\n\nThis notebook contains the actual dataset parser, patch generator, source-group split, ANN/CNN definitions, training, evaluation, controlled experiments, inference, and localization code. It does not import `src` modules. Generated outputs are intentionally empty until execution. Synthetic arithmetic examples teach mathematics; they are not PCB results.\n\nRun in the project `.venv` with all requirements installed. Download or manually extract DeepPCB, inspect its real files, and confirm the explicit schema/origin mapping before preprocessing. Training and all experiments can take hours on a CPU. See section 6 for controls. GitHub/PyPI were unavailable during generation; this notebook has not been executed end to end.')
    section(1,'Project Introduction','PCB manufacturing defects can break conductors, connect separate nets, or leave unwanted copper. We study visual patch classification with a custom CNN; electrical continuity and industrial reliability require separate validation.',example="import sys\nfrom pathlib import Path\nprint('Interpreter:', sys.executable)\nif '.venv' not in Path(sys.executable).parts:\n    raise RuntimeError('Select the PCB-Vision-AI .venv interpreter before executing this notebook.')\n")
    section(2,'Problem Statement','Given a grayscale PCB patch, predict one of seven classes. A full board may contain multiple defects, so its inspection is a separate experimental sliding-window task. Ground-truth boxes are used to form supervised crops, not supplied to the classifier at inference.')
    section(3,'Project Objectives','Train from scratch, avoid group leakage, quantify class-wise behavior, compare ANN/CNN, compare Adam/SGD, and measure augmentation effects. Preserve configurations and measured outputs instead of inventing accuracy.')
    section(4,'Deep Learning Fundamentals',r'An artificial neuron computes $z=\sum_i w_i x_i+b$ and applies an activation. ReLU is $\max(0,z)$. Softmax is $p_k=\exp(z_k)/\sum_j\exp(z_j)$. The example below is explicit ANN arithmetic on invented teaching inputs; it is not an inspection prediction.',example="import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom PIL import Image\nfrom IPython.display import display\n\ndef neuron(inputs, weights, bias):\n    return float(np.dot(inputs, weights) + bias)\n\ndef relu(values):\n    return np.maximum(0, values)\n\ndef stable_softmax(logits):\n    shifted = np.asarray(logits) - np.max(logits)\n    return np.exp(shifted) / np.exp(shifted).sum()\n\nprint('Teaching neuron:', neuron([0.2, 0.8], [0.5, -0.3], 0.1))\nprint('Teaching softmax:', stable_softmax([1.0, 2.0, 0.5]))\n")
    section(5,'Dataset Introduction','DeepPCB supplies aligned test/template pairs and six bounding-box defect IDs. Normal is generated outside annotations. The map keeps source IDs separate from display class indices; notably copper and pin-hole appear in a different display order.')
    section(6,'Dataset Download and Setup','The following cells define central settings and the real downloader inline. If downloading is blocked, extract the official ZIP and set `DATASET_DIRECTORY` to its actual `PCBData` directory. `CONFIRM_OBSERVED_SCHEMA` must be set only after section 7 displays real annotation lines and README evidence. Changing epochs changes the experiment budget and is recorded.',source='config/config.py',example="DATASET_DIRECTORY = CONFIG.dataset_dir\nCONFIRM_OBSERVED_SCHEMA = False\nRUN_TRAINING = True\nRUN_FULL_EXPERIMENTS = True\n# To shorten a smoke run, use dataclasses.replace(CONFIG, epochs=1) and label it a smoke run.\nCONFIG.validate()\n")
    code(inline_source('scripts/download_dataset.py'),'scripts/download_dataset.py')
    code("if not DATASET_DIRECTORY.is_dir():\n    DATASET_DIRECTORY = download_dataset(CONFIG.root / 'data' / 'raw')\nCONFIG = CONFIG.with_dataset(DATASET_DIRECTORY)\nprint('Dataset path:', CONFIG.dataset_dir)\n")
    section(7,'Dataset Structure Inspection','This full loader discovers actual filenames rather than assuming a single sibling folder layout. Rows must have five integers; unknown IDs and ambiguous files fail. Verify mapping/origin against the official README. Splitting is done now, before the demonstration crops later.',source='src/dataset_loader.py',example="dataset_summary = inspect_dataset(CONFIG.dataset_dir, CONFIG.annotation_origin, CONFIG.group_by_board)\ndisplay(dataset_summary)\nrecords = load_dataset(CONFIG.dataset_dir, CONFIG.annotation_origin, CONFIG.group_by_board)\nsplits = split_groups(records, CONFIG)\nassert_no_leakage(splits)\nprint({name: len(items) for name, items in splits.items()})\n")
    section(8,'Exploratory Data Analysis','The complete analysis functions below generate observed class counts and annotated images. Class support matters because an overall accuracy can hide a rare class. EDA observes label distribution, never uses test performance to choose training settings.',source='src/data_analysis.py',example="observed_counts = pd.Series(dataset_summary['counts_by_class'], name='Annotated defects')\ndisplay(observed_counts)\nobserved_counts.plot.barh(color='#15836b', title='Actual observed defect counts')\nplt.show()\n")
    # Decode is needed for visualization before the full preprocessing chapter.
