    section(32,'Visual Defect Localization',r'The complete implementation below batches overlapping windows, keeps sufficiently confident defect argmax classes, and applies class-aware NMS. $IoU=|A\cap B|/|A\cup B|$. Evaluation matches boxes one-to-one at a fixed IoU. Patch windows need not match the actual defect extent.',source='src/localization.py',example="if CONFIG.model_path.is_file():\n    predictor = Predictor(CONFIG.model_path, CONFIG)\n    localization_metrics = evaluate_localization(predictor, CONFIG, split='test')\n    display({key: localization_metrics[key] for key in ('image_count','precision','recall','mean_matched_iou')})\n    CONFIG.metrics_dir.joinpath('cnn_adam_aug','localization_test.json').write_text(json.dumps(localization_metrics, indent=2))\n")
    section(33,'Sample Predictions','Sample predictions come from actual held-out prepared patches. We display true and predicted classes only after a completed model is loaded; random-model examples are not presented as results.',example="if CONFIG.model_path.is_file():\n    predictor = Predictor(CONFIG.model_path, CONFIG)\n    sample_rows = frame[frame['split']=='test'].head(6)\n    figure, axes = plt.subplots(2,3,figsize=(12,7))\n    for axis, row in zip(axes.flat, sample_rows.itertuples()):\n        patch = read_image(CONFIG.processed_dir / row.patch_path)\n        prediction = predictor.predict_patch(patch)\n        axis.imshow(patch, cmap='gray'); axis.axis('off')\n        axis.set_title(f'True: {CLASS_NAMES[row.class_id]}\\nPredicted: {prediction.class_name} {prediction.confidence:.1%}', fontsize=9)\n    plt.tight_layout(); plt.show()\n")
