    section(36,'Inference on New PCB Images','Set `NEW_IMAGE_PATH` to an actual image. Uploaded decoding rejects unsupported/corrupt files and oversized images. Use patch prediction for one crop; use sliding-window inspection for a full board.',example="NEW_IMAGE_PATH = None\nif NEW_IMAGE_PATH is not None:\n    if not CONFIG.model_path.is_file():\n        raise FileNotFoundError('Train the CNN before new-image inference.')\n    new_image = decode_uploaded_image(Path(NEW_IMAGE_PATH).read_bytes())\n    new_inspection = inspect_image(new_image, Predictor(CONFIG.model_path, CONFIG), CONFIG)\n    display(draw_detections(new_image, new_inspection.detections))\nelse:\n    print('No new image selected; upload one through app.py or set NEW_IMAGE_PATH.')\n")
